/* ---------- Аппараты на орбите и пролётные миссии: точки на кольцах вокруг глобуса ----------
   Орбитальные аппараты никогда не ставятся на поверхность: внутреннее кольцо — орбита, внешнее — пролёт или облёт с возвращением. */
const RU_NAME = [[/^Luna (\d+)/, 'Луна-$1'], [/^Zond (\d+)/, 'Зонд-$1'], [/^Lunar Orbiter (\d)/, 'Лунар Орбитер-$1'], [/^Apollo (\d+)/, 'Аполлон-$1'], [/^Pioneer (\d+)/, 'Пионер-$1'],
  [/^Explorer (\d+)/, 'Эксплорер-$1'], [/^Mariner (\d+)/, 'Маринер-$1'], [/^Mars (\d+)$/, 'Марс-$1'], [/^Phobos (\d)/, 'Фобос-$1'], [/^Chang’e (\d)/, 'Чанъэ-$1'], [/^Chandrayaan-(\d)/, 'Чандраян-$1']];
const nameT = en => { let ru = en; for (const [re, to] of RU_NAME) if (re.test(en)) { ru = en.replace(re, to); break; } return T(en, ru, ru); };
const ORBIT_SKIP = new Set(['lunar-reconnaissance-orbiter', 'mars-odyssey']);   // у них есть своя 3D-модель на орбите
for (const [world, rows] of [['moon', CATALOG_MOON], ['mars', CATALOG_MARS]]) {
  const list = rows.filter(r => ['success', 'partial'].includes(r[6]) && ['orbit', 'flyby', 'returned', 'unknown'].includes(r[7]) && !ORBIT_SKIP.has(r[0]));
  for (const ring of ['orbit', 'flyby']) {
    const group = list.filter(r => (ring === 'orbit') === ['orbit', 'unknown'].includes(r[7]));
    const inc = (ring === 'orbit' ? 28 : -46) * Math.PI / 180;   // наклон кольца, чтобы точки не сливались в линию
    group.forEach((r, i) => {
      const th = (i + 0.5) * 2 * Math.PI / group.length;   // точки идут по кольцу в порядке запуска
      EXPLORE_SITES.push({ id: `o-${r[0]}`, mission: r[0], world, kind: 'orbiter', status: ring, lat: Math.asin(Math.sin(inc) * Math.sin(th)) * 180 / Math.PI,
        lon: Math.atan2(Math.cos(inc) * Math.sin(th), Math.cos(th)) * 180 / Math.PI, alt: ring === 'orbit' ? 0.16 : 0.34, inc, orbit: true,
        years: r[2].slice(0, 4), name: nameT(r[1]), ref: null, mini: true, explore: true });
    });
  }
}
for (const s of EXPLORE_SITES) s.desc = DESC[s.mission] || null;

